package com.fertiplus.product;
import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductRepository repo;public ProductController(ProductRepository r){repo=r;}@GetMapping public List<Product> all(){return repo.findAll();}@GetMapping("/{id}") public Product get(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));}@GetMapping("/sku/{sku}") public Product sku(@PathVariable String sku){return repo.findBySku(sku).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"SKU not found"));}}
